from pathlib import Path
import json,html,os
ROOT=Path(__file__).parent;D=ROOT/'dist';A=D/'assets'
ORIGIN=os.environ.get('URL','https://peter-idinga-gregztech.snuglion6.chatgpt.site').rstrip('/')
PUBLIC=os.environ.get('NETLIFY')=='true'
projects=json.loads((ROOT/'projects.json').read_text())


def head(title,desc,path='/'):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#151614"><title>{html.escape(title)}</title><meta name="description" content="{html.escape(desc)}"><meta name="robots" content="{"index,follow" if PUBLIC else "noindex,nofollow"}"><link rel="canonical" href="{ORIGIN}{path}"><meta property="og:title" content="{html.escape(title)}"><meta property="og:description" content="{html.escape(desc)}"><meta property="og:type" content="website"><meta property="og:image" content="{ORIGIN}/assets/social-preview.png"><meta property="og:url" content="{ORIGIN}{path}"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a>'''

def nav():
 return '''<header class="site-header"><a class="brand" href="/" aria-label="Gregztech — home"><img class="brand-logo" src="/assets/gregztech-wordmark.svg" alt="Gregztech" width="245" height="32"></a><nav class="desktop-nav" aria-label="Main navigation"><a href="/#work">Work <span>04</span></a><a href="/#about">About</a><a href="/#contact" class="nav-contact">Let’s talk <span aria-hidden="true">↗</span></a></nav><button class="menu-toggle" aria-expanded="false" aria-controls="mobile-menu">Menu <span aria-hidden="true">＋</span></button></header><dialog id="mobile-menu"><div class="menu-top"><span class="menu-logo"><img src="/assets/gregztech-wordmark.svg" alt="Gregztech" width="245" height="32"></span><button class="menu-close" aria-label="Close menu">Close ×</button></div><nav aria-label="Mobile navigation"><a href="/#work">Work <sup>04</sup></a><a href="/#about">About</a><a href="/#contact">Let’s talk ↗</a></nav><a class="menu-email" href="mailto:peteridinga@gmail.com">peteridinga@gmail.com</a></dialog>'''

def footer():
 return '''<section class="contact section" id="contact"><div class="eyebrow">HAVE A PROJECT IN MIND?</div><a class="contact-title" href="mailto:peteridinga@gmail.com">Tell me what you’re<br> working on. <span class="contact-arrow" aria-hidden="true">↗</span></a><div class="contact-bottom"><a class="email" href="mailto:peteridinga@gmail.com">peteridinga@gmail.com <span aria-hidden="true">↗</span></a><div class="socials"><a href="https://www.linkedin.com/in/peter-idinga" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><a href="https://x.com/Gregztech" target="_blank" rel="noopener noreferrer">X / Twitter ↗</a></div></div></section><footer class="footer"><span>© <span data-year>2026</span> Peter Idinga · Gregztech</span><span>Full-Stack Software Engineer</span><a href="#top">Back to top ↑</a></footer>'''

def visual(p,cls=''):
 shot=p['screens'][0]
 return f'''<div class="project-visual {cls}" style="--project:{p['color']};--project-dark:{p['dark']}"><div class="visual-caption"><span>{p['name'].upper()}</span><span>{p['label']}</span></div><div class="desktop-device"><div class="device-bar"><i></i><span>{p['url'].replace('https://','')}</span><span>↗</span></div><img src="/assets/{shot['asset']}.webp" alt="{p['name']} — {shot['title']}" width="{shot['width']}" height="{shot['height']}" loading="lazy"></div></div>'''

def gallery(p):
 figures=''
 for i,shot in enumerate(p['screens'][1:],2):
  figures+=f'''<figure class="screen-figure"><a class="screen-link" href="/assets/{shot['asset']}.webp" target="_blank" rel="noopener" aria-label="Enlarge {p['name']}: {shot['title']}"><img src="/assets/{shot['asset']}.webp" alt="{p['name']} — {shot['title']}" width="{shot['width']}" height="{shot['height']}" loading="lazy"><span class="enlarge">View full screen ↗</span></a><figcaption><span class="screen-number">0{i}</span><div><h3>{shot['title']}</h3><p>{shot['caption']}</p></div></figcaption></figure>'''
 return '<section class="screen-gallery section" aria-label="More project screens"><div class="gallery-heading"><span class="eyebrow">INSIDE THE EXPERIENCE</span><h2>A closer look.</h2><p>Selected views from the public website.</p></div>'+figures+'</section>'

cards=''
for i,pj in enumerate(projects):
 cards+=f'''<article class="project {'lead' if i<2 else 'secondary'}"><a class="visual-link" href="/work/{pj['slug']}/" aria-label="Explore {pj['name']} project">{visual(pj)}</a><div class="project-info"><div><span class="project-index">0{i+1} / {pj['industry']}</span><h3><a href="/work/{pj['slug']}/">{pj['name']} <span aria-hidden="true">↗</span></a></h3><p>{pj['summary']}</p></div><div class="project-actions"><span class="role">{pj['role']}</span><a href="/work/{pj['slug']}/">Explore project ↗</a><a class="muted-link" href="{pj['url']}" target="_blank" rel="noopener noreferrer">Visit website ↗</a></div></div></article>'''

homepage=head('Peter Idinga — Full-Stack Software Engineer | Gregztech','Peter Idinga builds websites and digital products, from interfaces to backend systems. Explore CEAVOX, HearIntel, QPrep and Safe Nest.')
homepage+='''<div id="intro" aria-hidden="true" hidden><div class="greeting"><span class="greeting-dot"></span><span id="greeting-word">Hello</span></div><div class="intro-bottom"><span>PETER IDINGA</span><span>GREGZTECH</span></div></div><div id="top"></div>'''+nav()+'''<main id="main"><section class="hero portrait-hero"><img class="hero-portrait" src="/assets/peter-idinga.webp" alt="Peter Idinga, also known as Gregztech" width="1253" height="1536" fetchpriority="high"><div class="portrait-shade"></div><div class="hero-occupation"><span aria-hidden="true">↘</span><p>Full-stack<br>software engineer.</p></div><h1>Peter Idinga<span class="name-period">.</span></h1><div class="portrait-bottom"><a href="#work" class="scroll-work">Scroll to explore <span aria-hidden="true">↓</span></a><p>Websites, applications,<br>and the systems behind them.</p><a href="mailto:peteridinga@gmail.com" class="portrait-contact">Let’s talk ↗</a></div></section><section class="personal-intro section"><p>I’m Peter. I build software from the first screen to the last API call.</p><div><p>My work spans event platforms, healthcare, education and housing. Below are four projects I’ve worked on—and what I brought to each.</p><a class="text-link" href="#about">A bit about me ↗</a></div></section><section class="work section" id="work"><div class="section-heading"><div><span class="eyebrow">SELECTED WORK / 01—04</span><h2>A few things<br>I’ve helped build.</h2></div><p>Frontend to backend.<br>Ideas to working products.</p></div><div class="projects">'''+cards+'''</div></section><section class="about section" id="about"><div class="about-top"><span class="eyebrow">ABOUT / PETER IDINGA</span><span class="eyebrow">ALSO KNOWN AS GREGZTECH</span></div><div class="about-layout"><div class="about-name"><span>Peter<br> Idinga.</span><a class="text-link" href="https://www.linkedin.com/in/peter-idinga" target="_blank" rel="noopener noreferrer">Find me on LinkedIn ↗</a></div><div class="about-copy"><h2>I like figuring out<br>how things work.<br>Then making them work.</h2><p>I’m a full-stack software engineer. I work on the interfaces people interact with, the logic behind them, and the data moving between the two.</p><p>Some projects need a clear, well-built website. Others need more: accounts, permissions, payments, or workflows that bring several people together. I enjoy connecting those pieces into one usable product.</p><p>CEAVOX, HearIntel and QPrep are full-stack projects I’ve worked on. My contribution to Safe Nest is frontend development.</p></div></div></section><section class="capabilities section"><div class="section-heading"><div><span class="eyebrow">WHAT I WORK ON</span><h2>What I can<br>help you build.</h2></div></div><div class="capability-list">'''
caps=[('01','Web interfaces','Responsive layouts, clear interactions and frontend development.'),('02','Applications & data','Backend logic, APIs, databases and the workflows connecting them.'),('03','Connected services','Authentication, permissions, payments and service integrations.'),('04','Getting it live','Testing, deployment and improvements as a product develops.')]
for n,t,d in caps:homepage+=f'<div class="capability"><span>{n}</span><h3>{t}</h3><p>{d}</p><span aria-hidden="true">↗</span></div>'
homepage+='</div></section></main>'+footer()+'</body></html>'
(D/'index.html').write_text(homepage)

for i,pj in enumerate(projects):
 path='/work/'+pj['slug']+'/'
 page=head(pj['name']+' — Project | Peter Idinga',pj['desc'],path)+'<div id="top"></div>'+nav()+f'''<main id="main" class="case-main"><section class="case-intro section"><a class="back-link" href="/#work">← Selected work</a><div class="case-kicker eyebrow">PROJECT 0{i+1} / {pj['industry'].upper()}</div><h1>{pj['name']}<span class="case-dot">.</span></h1><p class="case-summary">{pj['summary']}</p><div class="case-meta"><div><span>MY CONTRIBUTION</span><strong>{pj['role']}</strong></div><div><span>SECTOR</span><strong>{pj['industry']}</strong></div><a class="button" href="{pj['url']}" target="_blank" rel="noopener noreferrer">Visit live website ↗</a></div></section><div class="section case-visual">{visual(pj)}</div><section class="case-story section"><div class="story-heading"><span class="eyebrow">THE PROJECT</span><h2>{pj['desc']}</h2></div><div class="story-body"><h3>The challenge</h3><p>{pj['challenge']}</p><h3>My contribution</h3><p>{pj['contribution']}</p></div></section><section class="case-details section"><span class="eyebrow">A CLOSER LOOK</span><div class="decision-grid">'''
 for j,(t,d) in enumerate(pj['decisions']):page+=f'<div><span class="decision-number">0{j+1}</span><h3>{t}</h3><p>{d}</p></div>'
 page+='</div><div class="journey"><span class="eyebrow">THE USER JOURNEY</span><ol>'+''.join(f'<li><span>0{k+1}</span>{t}</li>' for k,t in enumerate(pj['journeys']))+'</ol></div>'
 if pj['tech']:page+='<div class="technology"><span class="eyebrow">CONFIRMED TECHNOLOGIES</span><div>'+''.join('<span>'+x+'</span>' for x in pj['tech'])+'</div></div>'
 page+=f'''<div class="outcome"><span class="eyebrow">THE PRODUCT</span><p>{pj['outcome']}</p></div></section>'''
 page+=gallery(pj)
 nxt=projects[(i+1)%4]
 page+=f'<section class="next-project section"><span class="eyebrow">NEXT PROJECT</span><a href="/work/{nxt["slug"]}/">{nxt["name"]} <span>↗</span></a></section></main>'+footer()+'</body></html>'
 out=D/'work'/pj['slug'];out.mkdir(parents=True,exist_ok=True);(out/'index.html').write_text(page)
(D/'404.html').write_text(head('Page not found | Gregztech','This page could not be found.')+'<div id="top"></div>'+nav()+'''<main id="main" class="section error-page"><span class="eyebrow">404 / A SMALL DETOUR</span><h1>This page took<br>a different path.</h1><p>Let’s get you back to the work.</p><a class="button" href="/">Back to the portfolio ↗</a></main>'''+footer()+'</body></html>')
(D/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n' if PUBLIC else 'User-agent: *\nDisallow: /\n')
(D/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+ORIGIN+p+'</loc></url>' for p in ['/']+['/work/'+x['slug']+'/' for x in projects])+'</urlset>')
print('Generated homepage, four case studies, 404 and metadata.')
